UNION ALL SELECT 53, 411098, 66534, 23911, 3281554, 560000, 'ثبت جدید Orders', 'چراغ مطالعه بوستانچی مدل DL-105 - سفید, سرویس ویژه زوم بازار: 7 روز تضمین بازگشت کالا', 0
UNION ALL SELECT 106, 411151, 66621, 32540, 3306477, 3700000, 'Orders قدیمی', 'بازی Need For Speed Unbound مخصوص PS5 ', 0
UNION ALL SELECT 55, 411172, 66679, 23992, 3282026, 9600000, 'ثبت جدید Orders', 'مخلوط کن 0.65 لیتری نینجا مدل BC251 - نسخه مستر کوالیتی - سبز, سرویس ویژه زوم بازار: 7 روز تضمین بازگشت کالا', 0
UNION ALL SELECT 136, 411290, 66825, 32616, 3306670, 4300000, 'Orders قدیمی', '1424', 0
UNION ALL SELECT 107, 411410, 66903, 32643, 3306737, 2057505, 'Orders قدیمی', 'دسته بازی تسکو مدل TG 120 ', 0
UNION ALL SELECT 56, 411477, 66919, 24122, 3283043, 860000, 'ثبت جدید Orders', 'چراغ مطالعه بوستانچی مدل EN-111 - مشکی, سرویس ویژه زوم بازار: 7 روز تضمین بازگشت کالا', 0
UNION ALL SELECT 108, 411749, 67055, 32696, 3306879, 850000, 'Orders قدیمی', 'کیف حمل کنسول پلی استیشن 5 اسلیم مدل Goku KE5119 slim', 0
UNION ALL SELECT 183, 411866, 67229, 32748, 3307026, 12300000, 'Orders قدیمی', 'هواپز 9 لیتر گوسونیک مدل GAF-879 - مشکی, سرویس ویژه زوم بازار: 7 روز تضمین بازگشت کالا', 0
UNION ALL SELECT 109, 411888, 67271, 32762, 3307060, 1210000, 'Orders قدیمی', 'ترازو دیجیتال کٌمری مدل PERSONAL SCALE ', 0
UNION ALL SELECT 112, 412136, 67442, 32826, 3307206, 4600000, 'Orders قدیمی', 'فر کننده مو شیگلم مدل 25mm ', 0
UNION ALL SELECT 187, 412367, 67533, 32848, 3307266, 5150000, 'Orders قدیمی', 'جارو برقی عصایی سیلور کرست مدل T01-SCB ظرفیت ۱۵۰۰ وات - مشکی, سرویس ویژه زوم بازار: 7 روز تضمین بازگشت کالا', 0
UNION ALL SELECT 114, 412382, 67573, 32863, 3318386, 5000000, 'Orders قدیمی', 'فر کننده مو شیگلم مدل 25mm ', 0
UNION ALL SELECT 142, 412400, 67614, 32879, 3318421, 13500000, 'Orders قدیمی', 'BG5475/15', 0
UNION ALL SELECT 140, 412861, 67721, 34683, 3324895, 11400000, 'Orders قدیمی', '6542/10', 0
UNION ALL SELECT 116, 412929, 67738, 34693, 3324989, 7800000, 'Orders قدیمی', 'بازی Gran Turismo 7 مخصوص PS5', 0
UNION ALL SELECT 190, 413025, 67831, 34758, 3325362, 10800000, 'Orders قدیمی', 'چای ساز روی هم میگل مدل GTS 230 - مشکی, گارانتی 60 ماهه سنجه کیش', 0
), live AS (
    SELECT p.*, oi.order_item_name,
           (SELECT COUNT(*) FROM `wp_woocommerce_order_itemmeta` pm
             WHERE pm.order_item_id = p.source_item_id AND pm.meta_key = '_zb_torob_purchase_price') AS purchase_meta_count,
           (SELECT MAX(pm.meta_value) FROM `wp_woocommerce_order_itemmeta` pm
             WHERE pm.order_item_id = p.source_item_id AND pm.meta_key = '_zb_torob_purchase_price') AS current_purchase
    FROM proposed p
    LEFT JOIN `wp_woocommerce_order_items` oi ON oi.order_item_id = p.source_item_id
 AND oi.order_id = p.source_order_id
 AND oi.order_item_type = 'line_item'
)
SELECT file_row AS `ردیف اکسل`, source_order_id AS `شناسه سفارش مبدأ`,
       source_item_id AS `شناسه قلم مبدأ`, central_order_id AS `سفارش Orders`,
       central_item_id AS `قلم Orders`, file_model AS `مدل فایل`,
       model_mismatch_in_central AS `مدل فایل با Orders نامنطبق بود`,
       order_item_name AS `عنوان قلم در سایت مبدأ`, price_origin AS `منبع قیمت هدف`,
       target_price AS `قیمت هدف`, current_purchase AS `قیمت فعلی مبدأ`,
       purchase_meta_count AS `تعداد متای قیمت`,
       CASE WHEN order_item_name IS NULL THEN 'قلم یا سفارش مبدأ پیدا نشد'
            WHEN purchase_meta_count > 1 THEN 'متای قیمت تکراری؛ رد شد'
            WHEN purchase_meta_count = 0 AND model_mismatch_in_central = 1
                 THEN 'آماده: افزودن قیمت؛ مدل فایل با Orders نامنطبق بود'
            WHEN purchase_meta_count = 0 THEN 'آماده: افزودن قیمت'
            WHEN current_purchase IS NULL OR TRIM(current_purchase) = ''
                 OR UPPER(TRIM(current_purchase)) = 'NULL' THEN 'آماده: تکمیل متای خالی'
            WHEN CAST(current_purchase AS DECIMAL(20,2)) = target_price
                 THEN 'قیمت مبدأ برابر است؛ بدون تغییر'
            ELSE 'قیمت موجود مبدأ متفاوت است؛ بررسی شود' END AS `نتیجه`
FROM live
ORDER BY file_row, source_item_id;
